{
  "name": "search_documents",
  "description": "Search authorized knowledge-base documents using a natural-language query.",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {"type": "string", "minLength": 1, "maxLength": 500},
      "limit": {"type": "integer", "minimum": 1, "maximum": 10},
      "category": {"type": "string", "enum": ["engineering", "support", "policy"]}
    },
    "required": ["query"],
    "additionalProperties": false
  }
}

def search_documents(query, limit=5):
    return {"query": query, "limit": limit, "results": []}

def get_service_status(service):
    return {"service": service, "status": "unknown"}

TOOLS = {"search_documents": search_documents, "get_service_status": get_service_status}

def dispatch_tool(name, arguments):
    if name not in TOOLS:
        raise ValueError(f"Unsupported tool: {name}")
    if not isinstance(arguments, dict):
        raise TypeError("Tool arguments must be an object")
    return TOOLS[name](**arguments)

def validate_search_arguments(arguments):
    if not isinstance(arguments, dict):
        raise TypeError("Expected an object")
    if set(arguments) - {"query", "limit"}:
        raise ValueError("Unexpected argument")
    query = arguments.get("query")
    limit = arguments.get("limit", 5)
    if not isinstance(query, str) or not query.strip() or len(query) > 500:
        raise ValueError("Invalid query")
    if type(limit) is not int or not 1 <= limit <= 10:
        raise ValueError("limit must be an integer from 1 to 10")
    return {"query": query.strip(), "limit": limit}

def run_agent(user_message, model_step, dispatch, max_steps=6):
    messages = [{"role": "user", "content": user_message}]
    for _ in range(max_steps):
        response = model_step(messages)
        if response.get("type") == "final":
            return response.get("content", "")
        if response.get("type") != "tool_call":
            raise ValueError("Unexpected model response")
        result = dispatch(response["name"], response["arguments"])
        messages.append({"role": "tool", "content": str(result)})
    raise RuntimeError("Tool-call step limit reached")
